attempts.query:
PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
SELECT ?name WHERE {
  {
    SELECT ?s (COUNT(DISTINCT ?t) AS ?n) WHERE {
      ?t a oncologia:Trial ; oncologia:sponsor ?s ; oncologia:status ?st ; oncologia:testsDrug ?d .
      FILTER(?st IN ("TERMINATED", "WITHDRAWN"))
      ?s oncologia:industry true .
      ?d oncologia:hasTarget ?tg . ?tg oncologia:gene ?g .
      FILTER(?g IN ("EGFR", "ERBB2", "ERBB3", "ERBB4"))
    }
    GROUP BY ?s
  }
  ?s oncologia:name ?name .
}
ORDER BY DESC(?n)
LIMIT 1
